import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import io from "socket.io-client";
import "./schedule.css";
import { BACKEND_URL } from "../../config";

const Schedule = () => {
  const user = JSON.parse(localStorage.getItem("user") || "null");
  const token = localStorage.getItem("token");
  const isAdmin = user?.role === "Admin";

  const [events, setEvents] = useState([]);
  const [activeEvent, setActiveEvent] = useState(null);
  const [selectedEventId, setSelectedEventId] = useState(null);

  const [teams, setTeams] = useState([]);
  const [matches, setMatches] = useState([]);
  const [loading, setLoading] = useState(true);

  // admin generate options
  const [venue, setVenue] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [tournamentType, setTournamentType] = useState("league");
  const [timeSlots, setTimeSlots] = useState(["Evening (5–8)"]);
  const [matchesPerDay, setMatchesPerDay] = useState(1);
  const [knockoutTeamsCount, setKnockoutTeamsCount] = useState(4);

  // edit match modal
  const [editMatch, setEditMatch] = useState(null);
  const [editDate, setEditDate] = useState("");
  const [editSlot, setEditSlot] = useState("");

  const [generating, setGenerating] = useState(false);

  const [socket] = useState(() =>
    io(BACKEND_URL, { auth: { token } })
  );

  const eventId = selectedEventId || activeEvent?._id;

  /* =======================
     FETCH EVENTS
  ======================= */
  const fetchEvents = useCallback(async () => {
    try {
      const res = isAdmin
        ? await axios.get(`${BACKEND_URL}/api/events`, {
            headers: { Authorization: `Bearer ${token}` }
          })
        : await axios.get(`${BACKEND_URL}/api/events/active`);

      const list = Array.isArray(res.data) ? res.data : [];
      setEvents(list);

      const active = list.find(e => e.isActive) || list[0];
      setActiveEvent(active || null);
      if (!selectedEventId && active) setSelectedEventId(active._id);
    } catch (err) {
      console.error("Fetch events failed", err);
    }
  }, [isAdmin, token, selectedEventId]);

  /* =======================
     FETCH TEAMS
  ======================= */
  const fetchTeams = useCallback(async (eid) => {
    if (!eid) return;
    try {
      const res = await axios.get(
        `${BACKEND_URL}/api/events/${eid}/teams`
      );
      setTeams(Array.isArray(res.data) ? res.data : []);
    } catch {
      setTeams([]);
    }
  }, []);

  /* =======================
     FETCH MATCHES
  ======================= */
  const fetchMatches = useCallback(async () => {
    if (!eventId) return;
    try {
      const res = await axios.get(
        `${BACKEND_URL}/api/schedule/${eventId}`
      );
      setMatches(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error("Fetch matches failed", err);
      setMatches([]);
    }
  }, [eventId]);

  /* =======================
     EFFECTS
  ======================= */
  useEffect(() => {
    fetchEvents();
  }, [fetchEvents]);

  useEffect(() => {
    if (!eventId) return;
    setLoading(true);
    Promise.all([fetchTeams(eventId), fetchMatches()])
      .finally(() => setLoading(false));
  }, [eventId, fetchTeams, fetchMatches]);

  useEffect(() => {
    socket.on("schedule:refresh", id => {
      if (id === eventId) fetchMatches();
    });
    return () => socket.off("schedule:refresh");
  }, [socket, eventId, fetchMatches]);

  /* =======================
     GENERATE SCHEDULE
  ======================= */
  const generateSchedule = async () => {
    if (!isAdmin) return alert("Admin only");
    if (!eventId) return alert("Select event");
    if (teams.length < 2) return alert("At least 2 teams required");

    setGenerating(true);
    try {
      await axios.post(
        `${BACKEND_URL}/api/schedule/generate`,
        {
          eventId,
          teams: teams.map(t => t._id),
          venue,
          startDate,
          endDate,
          tournamentType,
          timeSlots,
          matchesPerDay,
          knockoutTeamsCount
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      socket.emit("schedule:update", eventId);
      fetchMatches();
      alert("Schedule generated");
    } catch (err) {
      alert(err.response?.data?.error || "Schedule generation failed");
    } finally {
      setGenerating(false);
    }
  };

  /* =======================
     EDIT MATCH
  ======================= */
  const saveEdit = async () => {
    try {
      await axios.patch(
        `${BACKEND_URL}/api/schedule/match/${editMatch._id}`,
        {
          startTime: editDate,
          timeSlot: editSlot
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setEditMatch(null);
      fetchMatches();
    } catch {
      alert("Failed to update match");
    }
  };

  /* =======================
     SUBMIT WINNER
  ======================= */
  const submitWinner = async (matchId, teamId) => {
    try {
      await axios.post(
        `${BACKEND_URL}/api/schedule/match/${matchId}/result`,
        { winner: teamId },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchMatches();
    } catch {
      alert("Failed to submit result");
    }
  };

  /* =======================
     UI
  ======================= */
  return (
    <div className="schedule-page">
      <h1>Tournament Schedule</h1>

      {isAdmin && (
        <div className="schedule-generate-card">
          <h3>Generate Schedule</h3>

          <select value={tournamentType} onChange={e => setTournamentType(e.target.value)}>
            <option value="league">League</option>
            <option value="knockout">Knockout</option>
            <option value="league_knockout">League + Knockout</option>
          </select>

          <input placeholder="Venue" value={venue} onChange={e => setVenue(e.target.value)} />
          <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} />
          <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} />

          <label>Time Slots</label>
          <select multiple value={timeSlots}
            onChange={e => setTimeSlots([...e.target.selectedOptions].map(o => o.value))}>
            <option>Morning (9–12)</option>
            <option>Afternoon (1–4)</option>
            <option>Evening (5–8)</option>
          </select>

          <label>Matches per day</label>
          <input type="number" min="1" max="3"
            value={matchesPerDay}
            onChange={e => setMatchesPerDay(+e.target.value)} />

          {tournamentType !== "league" && (
            <select value={knockoutTeamsCount}
              onChange={e => setKnockoutTeamsCount(+e.target.value)}>
              <option value={2}>Top 2</option>
              <option value={4}>Top 4</option>
              <option value={8}>Top 8</option>
            </select>
          )}

          <button onClick={generateSchedule} disabled={generating}>
            {generating ? "Generating..." : "Generate Schedule"}
          </button>
        </div>
      )}

      {loading && <p>Loading matches...</p>}

      {!loading && matches.map(m => (
        <div
          key={m._id}
          className="match-row"
          onClick={() => {
            if (!isAdmin) return;
            setEditMatch(m);
            setEditDate(m.startTime?.slice(0, 10) || "");
            setEditSlot(m.timeSlot || "");
          }}
        >
          <strong>{m.homeTeam?.teamName || "TBD"}</strong>
          {" vs "}
          <strong>{m.awayTeam?.teamName || "TBD"}</strong>
          {" — "}
          {m.stage} | {m.timeSlot}

          {isAdmin && m.type === "Knockout" && !m.winner && (
            <div>
              <button onClick={() => submitWinner(m._id, m.homeTeam?._id)}>
                {m.homeTeam?.teamName} Won
              </button>
              <button onClick={() => submitWinner(m._id, m.awayTeam?._id)}>
                {m.awayTeam?.teamName} Won
              </button>
            </div>
          )}
        </div>
      ))}

      {editMatch && (
        <div className="modal">
          <h3>Edit Match</h3>
          <input type="date" value={editDate} onChange={e => setEditDate(e.target.value)} />
          <select value={editSlot} onChange={e => setEditSlot(e.target.value)}>
            <option>Morning (9–12)</option>
            <option>Afternoon (1–4)</option>
            <option>Evening (5–8)</option>
          </select>
          <button onClick={saveEdit}>Save</button>
          <button onClick={() => setEditMatch(null)}>Cancel</button>
        </div>
      )}
    </div>
  );
};

export default Schedule;
